// <diletta-rail-item> — a INSTÂNCIA WEB de `design-system-rail-item`.
//
// O `DilettaNav` do DS é barra INFERIOR de celular: mesma função de navegação,
// gramática diferente. Por isso esta peça é `destino: web` e não falta de paridade.
const ALVO = 44;
// SÃO TRÊS FORMAS, e a terceira entrou em 08/09 abrindo o conjunto do filho.
//
// | forma       | caixa   | onde                                              | usos |
// |-------------|---------|---------------------------------------------------|------|
// | `empilhado` | 160×78  | o rail aberto — glifo ACIMA do rótulo              | 162  |
// | `recolhido` | 70×70   | o rail fechado — só o medalhão de 38               | tela |
// | `emLinha`   | 168×28  | dentro de um painel «Menu» agrupado — glifo AO LADO| 10   |
//
// A terceira era o `Property 1=horizontal` do conjunto deles, e eu tinha lido esse
// eixo como estado × recolhido. Não é: é estado × ORIENTAÇÃO, e nenhuma das seis
// variantes publicadas é o rail recolhido — as duas orientações mostram rótulo.
// O recolhido saiu da tela, não do conjunto.
//
// > **O que muda entre as três é a DIREÇÃO da pilha e o que ela mostra, não a
// > anatomia.** Glifo, rótulo e estado são os mesmos nos três — por isso é um eixo
// > `forma`, e não três peças.
//
// As dez do `emLinha` estão em três telas, sempre em par dentro de um
// `Menu Header` de 200×188 com um título de grupo em cima («Performance», com
// «Visão geral» dentro; «Operação», com «Operação NRT»).
const CAIXA = { empilhado: [160, 78], recolhido: [70, 70], emLinha: [168, 28] };
const FORMA = ['empilhado', 'recolhido', 'emLinha'];
const MEDALHAO = 38;
// No painel agrupado o glifo é 16 e não 20, e o medalhão não existe: a caixa de 28
// não o comporta, e ali quem carrega o estado é a tinta do próprio par.
const GLIFO_EM_LINHA = 16;

class DilettaRailItem extends HTMLElement {
  static observedAttributes = ['estado', 'rotulo', 'href', 'forma'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  get ativo() { return this.getAttribute('estado') === 'ativo'; }
  get forma() {
    const v = this.getAttribute('forma');
    return FORMA.includes(v) ? v : 'empilhado';
  }

  render() {
    const on = this.ativo;
    const forma = this.forma;
    const emLinha = forma === 'emLinha';
    const rotulo = this.getAttribute('rotulo') || '';
    const [l, a] = CAIXA[forma];

    // `aria-current="page"` e não só cor: a spec pede que a seleção seja
    // ANUNCIADA, e cor sozinha não é portadora de informação (1.4.1).
    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        .item {
          box-sizing: border-box;
          width: ${l}px; min-height: ${Math.max(a, ALVO)}px;
          display: flex;
          flex-direction: ${emLinha ? 'row' : 'column'};
          align-items: center;
          justify-content: ${emLinha ? 'flex-start' : 'center'};
          gap: ${emLinha ? 8 : 6}px; text-decoration: none;
          color: var(--cps-${on ? 'primary' : 'textSecondary'});
        }
        /* A casca do glifo é o que carrega o estado no rail RECOLHIDO, onde o
           rótulo já não ajuda. Por isso ela não some com o rótulo. */
        .casca {
          width: ${emLinha ? GLIFO_EM_LINHA : MEDALHAO}px;
          height: ${emLinha ? GLIFO_EM_LINHA : MEDALHAO}px;
          border-radius: ${emLinha ? 0 : 12}px;
          flex: none;
          display: flex; align-items: center; justify-content: center;
          background: ${on && !emLinha ? 'var(--cps-primary)' : 'transparent'};
          color: var(--cps-${on ? (emLinha ? 'primary' : 'onPrimary') : 'textSecondary'});
        }
        .casca ::slotted(svg), .casca svg {
          width: ${emLinha ? GLIFO_EM_LINHA - 4 : 20}px;
          height: ${emLinha ? GLIFO_EM_LINHA - 4 : 20}px;
        }
        .rotulo { font-size: var(--cps-type-caption-size, 12px); }
        .item.emLinha .rotulo { font-size: inherit; }
        .item:focus-visible { outline: 3px solid var(--cps-primary); outline-offset: 2px; }
      </style>
      <a class="item ${forma}" part="item" href="${(this.getAttribute('href') || '#').replace(/"/g, '&quot;')}"
         ${on ? 'aria-current="page"' : ''} aria-label="${rotulo.replace(/"/g, '&quot;')}">
        <span class="casca"><slot name="icone"></slot></span>
        ${forma === 'recolhido' ? '' : `<span class="rotulo">${rotulo}</span>`}
      </a>`;
  }
}

customElements.define('diletta-rail-item', DilettaRailItem);
export { DilettaRailItem, ALVO, CAIXA, FORMA, MEDALHAO };
